package com.example.Hospital.Management.System.services; import com.example.Hospital.Management.System.entities.*; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.repositories.*; import com.example.Hospital.Management.System.exceptions.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class RoomService{private final RoomRepository r;private final HospitalRepository hr;public RoomService(RoomRepository r,HospitalRepository hr){this.r=r;this.hr=hr;} private Room find(Long id){return r.findById(id).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Room not found"));} private RoomDTO dto(Room e){return RoomDTO.builder().id(e.getId()).roomNumber(e.getRoomNumber()).floor(e.getFloor()).type(e.getType()).capacity(e.getCapacity()).hospitalId(e.getHospital().getId()).build();} private void apply(Room e,RoomDTO d){Hospital h=hr.findById(d.getHospitalId()).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Hospital not found"));e.setRoomNumber(d.getRoomNumber());e.setFloor(d.getFloor());e.setType(d.getType());e.setCapacity(d.getCapacity());e.setHospital(h);} public RoomDTO create(RoomDTO d){Room e=new Room();apply(e,d);return dto(r.save(e));} public List<RoomDTO> all(){return r.findByIsActiveTrue().stream().map(this::dto).toList();} public RoomDTO get(Long id){return dto(find(id));} public RoomDTO update(Long id,RoomDTO d){Room e=find(id);apply(e,d);return dto(r.save(e));} public void delete(Long id){Room e=find(id);e.setIsActive(false);r.save(e);} public List<RoomDTO> available(){return r.roomsWithCapacity().stream().map(this::dto).toList();}}
